// Child process for bench-files.ts: hosts the classroom so its CPU/RSS can be measured apart from the clients.
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { startClassroomServer } from '@classroom/server';

const host = process.argv[2] ?? '127.0.0.1';
// Test files are generated by the parent so generator garbage doesn't count toward this process's peak RSS.
const files = (process.argv[3] ?? '').split(',').filter(Boolean);
const dir = mkdtempSync(join(tmpdir(), 'bench-srv-'));
const s = await startClassroomServer({ title: 'Bench', host, storageDir: join(dir, 'storage'), limits: { downloadRequestsPerMinute: 100_000, pairInflightPerSource: 1000 } }); // all simulated students share one IP
s.classroom.setPolicy('open');
const resources = [];
for (const p of files) resources.push(await s.resources.importFile(p));
process.send!({ t: 'ready', url: s.url, bootstrapUrl: s.bootstrapUrl, sessionId: s.classroom.id, tls: s.tls, code: s.classroom.code, resources });
process.on('message', async (m: { t: string }) => {
  if (m.t === 'stats') process.send!({ t: 'stats', cpu: process.cpuUsage(), maxRssKb: process.resourceUsage().maxRSS, stats: s.resources.stats(0) });
  if (m.t === 'stop') { await s.close(); rmSync(dir, { recursive: true, force: true }); process.exit(0); }
});
